/bin/zsh -c "cat > migration.sql <<'EOF'
BEGIN;

-- Reject invalid imports before creating or changing any data.
DO "'$$
DECLARE invalid_id text;
BEGIN
  SELECT subscription_id INTO invalid_id
  FROM pricing_history WHERE fee_cents < 0 ORDER BY subscription_id LIMIT 1;
  IF invalid_id IS NULL THEN
    SELECT id INTO invalid_id FROM subscription
    WHERE (terms->>'"'monthlyFeeCents') ~ '"'^-?[0-9]+$'"'
      AND (terms->>'monthlyFeeCents')::numeric < 0
    ORDER BY id LIMIT 1;
  END IF;
  IF invalid_id IS NOT NULL THEN
    RAISE EXCEPTION 'negative fee for subscription %', invalid_id USING ERRCODE = 'P0001';
  END IF;
END "'$$;

CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL CHECK (fee_cents >= 0)
);

-- The approval date determines which historical price was approved. Older
-- subscriptions without history retain their legacy fee, or the minimum.
INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT s.id, COALESCE(h.fee_cents, (s.terms->>'"'monthlyFeeCents')::integer, 100)
FROM subscription s
LEFT JOIN LATERAL (
  SELECT fee_cents FROM pricing_history
  WHERE subscription_id = s.id AND effective_from <= s.approved_at
  ORDER BY effective_from DESC LIMIT 1
) h ON true;

COMMIT;
EOF
cat > subscriptions.ts <<'EOF'
export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents: _legacyFee, ...terms } = previous.terms;
  return { terms };
}

export function changedSinceApproval(subscription: any) {
  return getFee(subscription) "'!== subscription.terms.monthlyFeeCents;
}

export function acceptLegacyTerms(input: any) {
  if (!Number.isInteger(input.monthlyFeeCents) || input.monthlyFeeCents < 0) {
    throw new Error('"'invalid');
  }
  return input;
}
EOF
bun test"

