/bin/zsh -c "cat > smoke.test.ts <<'EOF'
import { test, expect } from 'bun:test';
import { acceptLegacyTerms, changedSinceApproval, getFee, MIN_FEE, newVersion } from './subscriptions';

test('decision supplies the fee, including zero', () => {
  expect(getFee({ pricingDecision: { feeCents: 2500 } })).toBe(2500);
  expect(getFee({ pricingDecision: { feeCents: 0 } })).toBe(0);
  expect(getFee({})).toBe(MIN_FEE);
});

test('a new version keeps other terms but requires a fresh fee decision', () => {
  const previous = { terms: { monthlyFeeCents: 2500, name: 'plan' }, pricingDecision: { feeCents: 2500 } };
  expect(newVersion(previous)).toEqual({ terms: { name: 'plan' } });
  expect(previous.terms.monthlyFeeCents).toBe(2500);
});

test('legacy terms remain accepted and comparable to the decision', () => {
  expect(acceptLegacyTerms({ monthlyFeeCents: 2500 }).monthlyFeeCents).toBe(2500);
  expect(() => acceptLegacyTerms({ monthlyFeeCents: -1 })).toThrow();
  expect(() => acceptLegacyTerms({ monthlyFeeCents: 1.5 })).toThrow();
  expect(changedSinceApproval({ terms: { monthlyFeeCents: 2500 }, pricingDecision: { feeCents: 2500 } })).toBe(false);
  expect(changedSinceApproval({ terms: { monthlyFeeCents: 2600 }, pricingDecision: { feeCents: 2500 } })).toBe(true);
});
EOF
bun test"

